inline float correction(int dx,int dy,unsigned sp,unsigned tp,int original_cheb) {
    if(kScope==0||(kScope==2&&original_cheb<=72))return 0.0f;
    const unsigned phase=((dx%10+10)%10)*12+(dy%12+12)%12;
    return source[sp*120+phase]+target[tp*120+phase];
}
